import{_ as o,o as d,c as r,a2 as c}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Rendering 模块概述与接入","description":"","frontmatter":{},"headers":[],"relativePath":"1.21.4/rendering/index.md","filePath":"1.21.4/rendering/index.md"}'),t={name:"1.21.4/rendering/index.md"};function i(n,e,a,l,s,p){return d(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="rendering-模块概述与接入" tabindex="-1">Rendering 模块概述与接入 <a class="header-anchor" href="#rendering-模块概述与接入" aria-label="Permalink to &quot;Rendering 模块概述与接入&quot;">​</a></h1><p><code>module.rendering</code> 在当前分支提供了两套专用于结构工程类 Mod 的客户端渲染管线：</p><ol><li><strong>世界内幽灵投影系统 (<code>projection</code>)</strong>：将任意局部 <code>ProjectionScene</code> 烘焙为可局部裁剪的轻量级 <code>VertexBuffer</code> 网格，采用**双通道先行（Depth Prepass + Color Pass）**机制消除半透明内部重叠 z-fighting，绕过光影管线直接在 <code>AFTER_LEVEL</code> 阶段输出半透明建筑蓝图，并对错方块/错方块状态自动高亮提示框。</li><li><strong>结构只读沙盒与 GUI 悬停 3D 预览 (<code>preview</code>)</strong>：提供轻量化沙盒渲染世界 <code>SandboxRenderLevel</code>、<code>ViewportCameraRig</code>、<code>StructurePreviewRenderer</code> 以及嵌入物品/界面提示区的动态弹窗管理器 <code>StructureGuiPreview</code>。</li></ol><h2 id="模块标识与入口" tabindex="-1">模块标识与入口 <a class="header-anchor" href="#模块标识与入口" aria-label="Permalink to &quot;模块标识与入口&quot;">​</a></h2><ul><li>模组 ID：<code>anvillib_rendering</code>（<code>AnvilLibRendering.MOD_ID</code>）</li><li>资源命名空间：<code>AnvilLibRendering.MOD_ID</code></li></ul><h2 id="核心着色器与渲染类型-projectionshaders-与-projectionrendertypes" tabindex="-1">核心着色器与渲染类型：<code>ProjectionShaders</code> 与 <code>ProjectionRenderTypes</code> <a class="header-anchor" href="#核心着色器与渲染类型-projectionshaders-与-projectionrendertypes" aria-label="Permalink to &quot;核心着色器与渲染类型：`ProjectionShaders` 与 `ProjectionRenderTypes`&quot;">​</a></h2><p><code>ProjectionShaders</code> 通过 NeoForge <code>@EventBusSubscriber(modid = AnvilLibRendering.MOD_ID, value = Dist.CLIENT)</code> 挂载客户端事件，使用 <code>net.minecraft.client.renderer.ShaderProgram</code> 注册内置核心着色器 <code>anvillib_rendering:core/projection</code>（顶点格式 <code>DefaultVertexFormat.BLOCK</code>）。</p><table tabindex="0"><thead><tr><th>类 / 成员</th><th>作用域</th><th>说明</th></tr></thead><tbody><tr><td><code>ProjectionShaders.register(RegisterShadersEvent event)</code></td><td><code>public static</code></td><td>向 <code>RegisterShadersEvent</code> 注册 <code>anvillib_rendering:core/projection</code> <code>ShaderProgram</code></td></tr><tr><td><code>ProjectionShaders.reload(ModelEvent.BakingCompleted event)</code></td><td><code>public static</code></td><td>资源包或方块模型重新烘焙完成后自增版本号 <code>generation</code> 并清空 <code>ProjectionRenderTypes</code> 缓存，使旧投影网格在下一帧检测到 <code>isValid() == false</code> 并触发重建</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>由于模型烘焙重载会使缓存的 <code>ProjectionRenderer</code> 失效（<code>isValid()</code> 返回 <code>false</code>），调用方在每帧准备绘制前应检查 <code>renderer.isValid()</code>；一旦返回 <code>false</code>，需要重新构造或调用 <code>renderer.rebuild(scene, alpha)</code>，确保图集 UV 与区块模型一致。</p></div><h2 id="projectionbuffers-内部多类型缓冲分配器" tabindex="-1"><code>ProjectionBuffers</code>（内部多类型缓冲分配器） <a class="header-anchor" href="#projectionbuffers-内部多类型缓冲分配器" aria-label="Permalink to &quot;`ProjectionBuffers`（内部多类型缓冲分配器）&quot;">​</a></h2><p><code>ProjectionBuffers</code> 实现了 <code>MultiBufferSource</code> 与 <code>AutoCloseable</code>，用于承接 <code>BlockEntityRenderer</code> 与 <code>EntityRenderDispatcher</code> 在虚拟场景中发射的几何顶点：</p><ul><li>按传入的原版 <code>RenderType</code> 映射到 <code>ProjectionRenderTypes.ghost(type, depthOnly)</code>，自动关闭透明通道外的深度遮挡冲突；</li><li>为每个顶点自动乘算并覆盖投影整体透明度 <code>opacity</code>，并在绘制深度通道时使用 <code>depthMask(true) + colorMask(false, false, false, false)</code>，在颜色通道时切换回 <code>depthMask(false) + colorMask(true, true, true, true)</code>。</li></ul>',12)])])}const f=o(t,[["render",i]]);export{u as __pageData,f as default};
